<?php require "config/db.php"; require "includes/functions.php"; $q=trim($_GET["q"]??""); $s=$conn->prepare("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.status='active' AND (p.name LIKE ? OR p.description LIKE ?) ORDER BY p.id DESC");$like="%$q%";$s->execute([$like,$like]);$products=$s->fetchAll();$page_title="Products";require "includes/header.php";?>
<div class="d-flex justify-content-between align-items-center mb-4"><h2>Groceries</h2><form class="d-flex"><input class="form-control me-2" name="q" value="<?=e($q)?>" placeholder="Search products"><button class="btn btn-primary">Search</button></form></div><div class="row g-4"><?php foreach($products as $p):?><div class="col-md-4"><div class="card h-100 p-3"><div class="ratio ratio-4x3 bg-light mb-3"><?php if($p["image"]):?><img src="<?=e($p["image"])?>" class="object-fit-cover"><?php endif;?></div><h5><?=e($p["name"])?></h5><p class="text-muted"><?=e($p["description"]??"")?></p><strong>₵<?=number_format($p["price"],2)?></strong></div></div><?php endforeach;?></div><?php require "includes/footer.php"; ?>